-- Ambos resultados confirmados por el propietario el 14/10/2026; sólo documentación.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('devolver-acuerdo-anticipado',$texto$Devolver un acuerdo anticipado: $100 parcial y $1,300 restantes$texto$,'Cobranza',$texto$Devolver primero $100 conservando el beneficio y después todo lo restante, revirtiendo el beneficio adicional y conservando la beca. Comprobar abonos, cuenta, acuerdo y portal familiar en cada etapa.$texto$,$texto$Se parte del pago validado de $1,400.00 del caso ANTICIPO-TEST-05, con noviembre y diciembre de 2026, originales $1,000.00, beca $200.00 y beneficio fijo $100.00 por mes. Abonos iniciales $700.00 por mes, ambos saldos cero; acuerdo aplicado, sin devoluciones previas ni disponible sin aplicar. Consultar primero la guía Pago anticipado: beneficio fijo total de $200 conservando beca si hay que preparar un nuevo ensayo; no repetir el caso ya terminado. Cuenta original activa con fondos suficientes y administrador identificado autorizado. No usar el pago anual de $11,000.00 ni el de otra variante. No realizar transferencias reales para ensayar; las operaciones las captura el usuario, no el agente.$texto$,$texto$Situación inicial: noviembre700 y diciembre700 abonados. Primera devolución100 de noviembre: abono600/deuda100; diciembre700/deuda0; beneficio100 por mes conservado y cuenta menos100. Segunda devolución1300 (600+700): devuelto acumulado1400; sin abonos vigentes, beneficio100 por mes reversado, beca200 conservada y adeudos800 por mes. Acuerdo cancelado, cuenta menos1400 respecto de antes de ambas devoluciones y pago con historial conservado. Un adeudo de400 del otro hijo era independiente, no un efecto de estas devoluciones. Ambos resultados confirmados por el propietario.$texto$,1,DATE '2026-10-14','CONFIRMADA');

INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['PAGO_LEER','PAGO_DEVOLVER','CARGO_ADMINISTRAR','CONVENIO_PAGO_ADMINISTRAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='devolver-acuerdo-anticipado';

INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('devolver-acuerdo-anticipado',1,$texto$Localizar el pago y comprobar su situación inicial$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Distribución$texto$,$texto$1. Entra a Administración → Finanzas → Pagos recibidos → Limpiar. En Concepto de cobro escribe ANTICIPO-TEST-05; opcionalmente en Buscar escribe el tutor o folio, selecciona Estado Validado y pulsa Aplicar filtros. 2. Abre Ver del pago por $1,400.00 y anota su folio; en Resumen comprueba alumno, tutor, plantel, cuenta y acuerdo vinculado. No uses el pago anual de $11,000.00 ni otro pago que tenga el mismo importe. 3. Abre Distribución: noviembre y diciembre deben tener abono vigente $700.00 cada uno y saldo $0.00; Disponible $0.00. En Devoluciones comprueba que todavía no exista devolución ejecutada para iniciar un ensayo nuevo. 4. Desde Resumen → Ver acuerdo y mensualidades comprueba beneficio aplicado de $200.00 total, repartido $100.00 por mes y beca conservada $200.00 por mes. Si el caso ya fue devuelto, consulta el historial y no repitas capturas.$texto$,$texto$Dos originales1000, beca200 y beneficio100 por mes; pago700+700=1400.$texto$,$texto$Pago y acuerdo correctos identificados.$texto$,$texto$No asumir IDs o folios de otra base de datos; la devolución sólo debe afectar este pago.$texto$,$texto$/admin/catalogos/pagos$texto$),
('devolver-acuerdo-anticipado',2,$texto$Anotar la cuenta y saldo previo a ambas devoluciones$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Entra a Administración → Finanzas → Cuentas financieras, busca la cuenta destino identificada en el pago → Aplicar filtros. 2. Anota Saldo actual como S, no Saldo inicial; confirma cuenta activa y fondos suficientes. Conserva este valor antes de ejecutar cualquier devolución. 3. Para comparar sin ambigüedad evita otros movimientos concurrentes en la misma cuenta durante el ensayo. No alteres saldo inicial ni captures un movimiento manual para obtener los resultados esperados. 4. Vuelve a Administración → Finanzas → Pagos recibidos, filtra ANTICIPO-TEST-05 y abre Ver del folio → Devoluciones. Si consultas un caso histórico, usa los movimientos del propio pago para distinguirlo de otros ingresos o egresos posteriores.$texto$,$texto$Si S fuera $20,000.00, tras devolver100 queda $19,900.00 y tras devolver otros1300 queda $18,600.00; cifras ilustrativas.$texto$,$texto$Referencia S preparada para verificar egresos.$texto$,$texto$S es saldo actual antes de devolver, no saldo antes de recibir los1400. Se restan100 y1300, sin ingreso compensatorio.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('devolver-acuerdo-anticipado',3,$texto$Capturar la devolución parcial de noviembre$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Devoluciones → Ejecutar devolución$texto$,$texto$1. En Ver del mismo pago → Devoluciones → Ejecutar devolución conserva Cuenta de origen original; no actives Devolver desde otra cuenta. Captura Fecha y hora reales actuales, no futuras. 2. Selecciona Tipo de devolución Devolución parcial y Dinero a devolver 100.00; Beneficiario: nombre del tutor; Referencia: DEV-PARCIAL-ANTICIPO-05-100. 3. Captura Motivo: Prueba de devolución parcial de $100 sobre noviembre. Se conserva el beneficio del acuerdo anticipado. En Abonos de los que se devolverá dinero marca únicamente noviembre por $700.00 y deja diciembre desmarcado. La tarjeta seleccionada se resalta y muestra Seleccionado. 4. Lee Revisión obligatoria del acuerdo anticipado y marca Revisé las condiciones y autorizo este tratamiento del beneficio. No selecciones cargos de otro hijo ni declares disponible adicional.$texto$,$texto$Devolver $100.00 tomando sólo el abono de noviembre700.$texto$,$texto$Captura preparada sin publicar egreso todavía.$texto$,$texto$Elegir Devolución total con sólo noviembre devolvería todo ese abono seleccionado, no los100 del ejercicio.$texto$,$texto$/admin/catalogos/pagos$texto$),
('devolver-acuerdo-anticipado',4,$texto$Revisar y ejecutar los primeros $100$texto$,$texto$Administración$texto$,$texto$Devoluciones → Así quedaría la devolución$texto$,$texto$1. En Así quedaría la devolución revisa Dinero a devolver $100.00, Abono seleccionado que permanecerá aplicado $600.00 y Deuda que se recuperará $100.00; sólo debe figurar noviembre. 2. Comprueba cuenta de origen, beneficiario, fecha, referencia y motivo. El pago conserva el estado validado y esta devolución parcial conserva el beneficio del acuerdo. 3. Pulsa Ejecutar devolución y publicar egreso; revisa el modal, monto y cuenta, y confirma una sola vez si todo coincide. Cancelar el modal no debe ejecutar la devolución; si lo cancelas, vuelve a confirmar únicamente cuando estés listo. 4. Revisa Historial de dinero devuelto: debe existir una devolución ejecutada por $100.00; conserva su folio. No pulses Cancelar pago registrado por error ni repitas la operación si ya aparece ejecutada.$texto$,$texto$Primera devolución100, sin tocar el abono700 de diciembre.$texto$,$texto$Egreso parcial publicado con trazabilidad.$texto$,$texto$Devolver dinero no es cancelar un pago por captura errónea; después de devoluciones la cancelación del pago está bloqueada.$texto$,$texto$/admin/catalogos/pagos$texto$),
('devolver-acuerdo-anticipado',5,$texto$Verificar efecto parcial en adeudos, acuerdo y cuenta$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos, Acuerdos y Cuentas financieras$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; en Buscar escribe alumno o matrícula y en Concepto de cobro ANTICIPO-TEST-05 → Todos → Aplicar filtros. Abre Ver noviembre: abono vigente $600.00, beneficio adicional $100.00, beca $200.00 y saldo pendiente $100.00. 2. Vuelve al listado con los filtros conservados y abre Ver diciembre: abono vigente $700.00, beca $200.00, beneficio adicional $100.00 y saldo $0.00. 3. Entra a Operación escolar → Cobranza escolar → Convenios de pago → Acuerdos por pago anticipado, busca el folio → Ver: beneficio continúa aplicado; la devolución parcial no elimina el beneficio. 4. En Administración → Finanzas → Cuentas financieras consulta la cuenta original: saldo S menos $100.00 y un egreso100 de esta devolución. Si hubo otros movimientos, contrasta también el historial financiero del pago.$texto$,$texto$Noviembre600 abonados/saldo100; diciembre700/saldo0; beneficio100 por mes conservado.$texto$,$texto$Primera etapa confirmada, cuenta disminuida exactamente100.$texto$,$texto$No pagues los100 recuperados ni apliques descuento manual: se requiere conservar ese estado para devolver después el resto.$texto$,$texto$/admin/catalogos/cargos$texto$),
('devolver-acuerdo-anticipado',6,$texto$Comprobar el pendiente parcial en el portal familiar$texto$,$texto$Tutor y administración$texto$,$texto$Portal familiar → Tus pagos$texto$,$texto$1. En ventana privada u otro navegador entra a /familias con el tutor autorizado. Selecciona el hijo del acuerdo → Tus pagos. 2. Comprueba que aparece noviembre de ANTICIPO-TEST-05 por $100.00 pendiente; diciembre no debe tener saldo exigible en esta etapa. 3. Si aparecen otros adeudos, consulta alumno, concepto y periodo; en el ensayo había $400.00 pendientes del otro hijo, ajenos a la devolución. No confundas el total familiar con la deuda de este acuerdo. 4. Conserva evidencia y no reportes transferencia para esos100; regresa a la sesión administrativa para probar la devolución del restante. No canceles otros cargos para que la pantalla muestre sólo el ensayo.$texto$,$texto$Deuda recuperada100 del hijo del acuerdo; otro adeudo400 no cambia.$texto$,$texto$Primera etapa familiar confirmada e identificada por alumno.$texto$,$texto$Las pestañas normales comparten sesión; usa ventana privada o navegador separado para no sustituir el acceso administrativo.$texto$,$texto$/admin/catalogos/pagos$texto$),
('devolver-acuerdo-anticipado',7,$texto$Preparar la devolución de los $1,300 restantes$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Devoluciones$texto$,$texto$1. Entra a Administración → Finanzas → Pagos recibidos, busca ANTICIPO-TEST-05 y el mismo folio → Ver → Devoluciones. Comprueba Devuelto acumulado $100.00 y abonos vigentes noviembre600/diciembre700, sin disponible adicional. 2. En Ejecutar devolución conserva Cuenta de origen original, captura fecha y hora reales y selecciona Devolución total. En Abonos de los que se devolverá dinero marca ambos abonos: noviembre600 y diciembre700. 3. Dinero a devolver debe calcularse protegido en $1,300.00; captura Beneficiario con nombre del tutor, Referencia DEV-RESTO-ANTICIPO-05-1300 y Motivo: Devolución del importe restante del acuerdo anticipado. Se devuelve todo el pago y se revierte el beneficio adicional, conservando la beca original. 4. Lee y marca Revisé las condiciones y autorizo este tratamiento del beneficio. Esta vez el acumulado100+1300 cubre todo el pago1400 y activa la reversión del beneficio adicional.$texto$,$texto$Abonos vigentes600+700=1300; devolución previa100 más nueva1300=1400.$texto$,$texto$Captura del restante completo preparada.$texto$,$texto$Total significa todos los abonos seleccionados y disponible sin aplicar; marcar sólo uno no devuelve todo el restante del pago.$texto$,$texto$/admin/catalogos/pagos$texto$),
('devolver-acuerdo-anticipado',8,$texto$Revisar el tratamiento del beneficio y ejecutar el restante$texto$,$texto$Administración$texto$,$texto$Devoluciones → Vista previa y confirmación$texto$,$texto$1. Revisa vista previa de dinero a devolver $1,300.00 y abonos seleccionados que permanecerán aplicados $0.00; cuenta y beneficiario deben ser correctos. 2. Ten presente que liberar los abonos600+700 no es todo el cambio de deuda: al devolver el total acumulado también se revierten los descuentos del acuerdo de100 por mes. La deuda final se comprobará en Adeudos de alumnos, no sólo con la cifra de abonos liberados de la vista previa. 3. Pulsa Ejecutar devolución y publicar egreso, revisa el modal y confirma una sola vez por $1,300.00. No ejecutes un egreso manual ni pulses Cancelar pago para completar el ejercicio. 4. En Historial de dinero devuelto comprueba dos operaciones ejecutadas: $100.00 y $1,300.00; acumulado $1,400.00. El pago conserva historial y no debe quedar dinero restante por devolver.$texto$,$texto$Dinero total devuelto1400, beneficio adicional total200 revertido, sin segundo ingreso.$texto$,$texto$Restante devuelto, tratamiento integral del acuerdo ejecutado.$texto$,$texto$No restes otra vez los100 anteriores: esta segunda operación devuelve únicamente1300.$texto$,$texto$/admin/catalogos/pagos$texto$),
('devolver-acuerdo-anticipado',9,$texto$Verificar beca conservada, beneficio revertido y cuenta$texto$,$texto$Administración$texto$,$texto$Acuerdos, Adeudos de alumnos y Cuentas financieras$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Convenios de pago → Acuerdos por pago anticipado, busca el folio → Ver: debe quedar cancelado tras devolver todo; la propuesta se conserva como historial y no como beneficio vigente. 2. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; Busca alumno, Concepto de cobro ANTICIPO-TEST-05 → Todos → Aplicar filtros → Ver noviembre → Resumen e Historial. Original1000, beca200 conservada, descuento100 del acuerdo revertido, sin abono vigente y saldo pendiente800. 3. Vuelve al listado y abre Ver diciembre: mismos valores original1000/beca200/beneficio100 revertido/sin abono/saldo800. La beca original no se elimina; ambos cargos vuelven a exigir800 cada uno. 4. Entra a Administración → Finanzas → Cuentas financieras y consulta la cuenta: disminuye otros1300 respecto a después de la primera devolución; saldo S menos1400 respecto al inicio de ambas. Revisa los dos egresos sin duplicación.$texto$,$texto$Dos deudas800, total1600; beca200 por mes conservada, descuento100 por mes revertido.$texto$,$texto$Segunda etapa administrativa confirmada por el propietario.$texto$,$texto$No confundir el saldo por pagar1600 con dinero devuelto1400: los200 de diferencia son el beneficio adicional que ya no corresponde.$texto$,$texto$/admin/catalogos/cargos$texto$),
('devolver-acuerdo-anticipado',10,$texto$Comprobar portal e historial y cerrar el ensayo$texto$,$texto$Tutor y administración$texto$,$texto$Portal familiar y Pagos recibidos$texto$,$texto$1. En ventana privada entra a /familias como tutor → selecciona el hijo → Tus pagos: deben aparecer noviembre y diciembre de ANTICIPO-TEST-05 por $800.00 pendientes cada uno. 2. Verifica que los otros adeudos familiares, como los400 del otro hijo, permanecen independientes. No los pagues o canceles para modificar el resultado de este ensayo. 3. En administración abre el mismo pago → Devoluciones: conserva historial100+1300=1400 y sus motivos. No debe aparecer otra devolución ni un ingreso compensatorio; el acuerdo cancelado permanece consultable. 4. Conserva evidencias y termina sin registrar nuevos pagos ni descuentos. El propietario confirmó ambas etapas el14/10/2026; seguridad de cargo duplicado, cancelar confirmación y validar un mismo pago desde dos pestañas son los tres ensayos pendientes.$texto$,$texto$Portal muestra800+800 del hijo correcto; devolución acumulada1400 e historial conservado.$texto$,$texto$Proceso de devolución parcial y completa confirmado.$texto$,$texto$Si reproduces después, prepara otro caso controlado. No puedes devolver nuevamente el pago ya devuelto completo.$texto$,$texto$/admin/catalogos/pagos$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;

-- Actualización editorial de referencias antiguas, nunca de cargos/pagos/cuentas.
UPDATE guia_proceso_paso SET precaucion=$texto$Las devoluciones parcial100 y restante1300 del beneficio fijo ya fueron confirmadas y tienen guía propia: Devolver un acuerdo anticipado. Consulta esa guía para ver conservación/reversión del beneficio y beca. No repetir las operaciones del caso terminado. Cargo duplicado, cancelar confirmación y validar el mismo pago desde dos pestañas siguen pendientes.$texto$
WHERE (guia_id IN (SELECT id FROM guia_proceso WHERE slug IN ('pago-anticipado-beca-porcentaje','anticipo-mensualidad-bonificada','anticipo-sustituir-beca','anticipo-beneficio-fijo')) AND numero=10)
   OR (guia_id IN (SELECT id FROM guia_proceso WHERE slug IN ('cancelar-pago-anticipado-beca','pago-anual-diciembre-bonificado')) AND numero=12);
UPDATE guia_proceso_paso SET ejemplo=replace(ejemplo,'No devolver ni cancelar al terminar: ese pago1400 se utilizará después para ensayar devolución parcial100 y restante1300, aún pendientes de confirmación.','Las devoluciones posteriores100 y1300 ya están confirmadas y se documentan en la guía Devolver un acuerdo anticipado; no repetirlas sobre el pago ya devuelto.')
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='anticipo-beneficio-fijo') AND numero=10;
UPDATE guia_proceso_paso SET precaucion=$texto$No cancelar el pago ni aplicar descuentos manuales para cerrar el ejercicio. Las devoluciones del otro acuerdo de1400 ya tienen guía confirmada; no afectan este pago anual. Sólo las tres pruebas de seguridad siguen pendientes.$texto$
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='pago-anual-diciembre-bonificado') AND numero=11;
UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-14'
WHERE slug IN ('pago-anticipado-beca-porcentaje','anticipo-mensualidad-bonificada','anticipo-sustituir-beca','anticipo-beneficio-fijo','cancelar-pago-anticipado-beca','pago-anual-diciembre-bonificado');
